import crypto from 'node:crypto';
import { config } from '../config.js';
import { User } from '../models/index.js';

// Verifies the signed initData that Telegram gives the Mini App.
// https://core.telegram.org/bots/webapps#validating-data-received-via-the-mini-app
export function verifyInitData(initData, botToken, maxAgeSec = 86400) {
  if (!initData || !botToken) return null;
  const params = new URLSearchParams(initData);
  const hash = params.get('hash');
  if (!hash) return null;
  params.delete('hash');

  const dataCheck = [...params.entries()]
    .map(([k, v]) => `${k}=${v}`)
    .sort()
    .join('\n');
  const secret = crypto.createHmac('sha256', 'WebAppData').update(botToken).digest();
  const calc = crypto.createHmac('sha256', secret).update(dataCheck).digest('hex');

  const a = Buffer.from(calc, 'hex');
  const b = Buffer.from(hash, 'hex');
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return null;

  const authDate = Number(params.get('auth_date'));
  if (!authDate || Date.now() / 1000 - authDate > maxAgeSec) return null;

  try {
    return JSON.parse(params.get('user'));
  } catch {
    return null;
  }
}

export const isAdminId = (id, user) => config.adminIds.includes(id) || user?.role === 'ADMIN';

// Fastify preHandler: puts request.user (mongoose doc) and request.isAdmin
export async function requireUser(request, reply) {
  let tgUser = verifyInitData(request.headers['x-init-data'], config.botToken);

  // Local testing without Telegram (DEV_MODE=true only)
  if (!tgUser && config.devMode && request.headers['x-dev-user']) {
    const id = Number(request.headers['x-dev-user']);
    if (id) tgUser = { id, first_name: 'Dev User' };
  }
  if (!tgUser) return reply.code(401).send({ error: 'unauthorized' });

  let user = await User.findOne({ telegramId: tgUser.id });
  if (!user && config.devMode) {
    user = await User.create({
      telegramId: tgUser.id,
      firstName: tgUser.first_name,
      language: 'en',
      phone: '+251900000000',
    });
  }
  if (!user) return reply.code(401).send({ error: 'start_bot_first' });

  request.user = user;
  request.isAdmin = isAdminId(user.telegramId, user);
}

export async function requireAdmin(request, reply) {
  await requireUser(request, reply);
  if (reply.sent) return;
  if (!request.isAdmin) return reply.code(403).send({ error: 'forbidden' });
}
